INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (8, 7, 'theory', 'Quiz: interrupts, deferred work, and time');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 7, 0, 'Why is an interrupt handler split into a top half and a bottom half?', '["The top half runs in user mode", "The bottom half always runs on another processor", "The split is needed only for debugging", "The top half quickly acknowledges the interrupt, while long work is deferred and doesn''t delay other events"]', 3, 'While the top half runs, some interrupts are muted. So only the most urgent work is done in it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 7, 1, 'What must you not do in a softirq?', '["Access memory", "Sleep, that is, wait for an event or take a sleeping lock", "Run on several cores", "Call the scheduler indirectly"]', 1, 'A softirq runs outside process context, so there is nothing to put to sleep. If you need to sleep, use a workqueue.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 7, 2, 'What replaces tasklets in modern kernels?', '["Bottom halves on workqueues (BH workqueues), introduced in kernel 6.9", "Spinlocks", "User threads", "hrtimer timers"]', 0, 'Tasklets are deprecated, and drivers are gradually being moved to a new interface with proper cancellation.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 7, 3, 'Where should you send deferred work that needs to sleep?', '["To a tasklet", "To the top half of the handler", "To a workqueue: it is run by kworker threads in process context", "To a separate softirq"]', 2, 'Process context allows sleeping, allocating memory with waiting, and working with files.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 7, 4, 'What does NO_HZ mode do?', '["Turns off all interrupts in the system", "Turns off the periodic tick on idle cores to save energy", "Speeds the tick up to one gigahertz", "Forbids the use of timers"]', 1, 'The scheduler needs the tick, but waking an idle core just for that is wasteful. Precise time comes from the processor''s counter.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 7, 5, 'Why must a hardware interrupt handler be short?', '["Because its code is small", "Because interrupts can''t be handled on several cores", "Because the device will time out after exactly one millisecond", "While it runs, the kernel can''t do anything else on that processor, and it can''t sleep, so long work is deferred"]', 3, 'The top half only acknowledges the device and queues the rest of the work for deferred execution: softirqs, workqueues, threaded interrupts.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 7, 6, 'How does a workqueue fundamentally differ from a softirq?', '["It is faster, because it runs in interrupt context", "It is launched only once a second", "The work runs in a kernel thread in process context, so it can sleep, for example while waiting for a disk", "It works exclusively in user space"]', 2, 'Softirqs don''t sleep. If deferred work needs to wait or take a mutex, it is handed to a workqueue.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 7, 7, 'Why does the kernel need high-resolution timers (hrtimer) if it has ticks?', '["They fire at the right moment with nanosecond precision and aren''t tied to the tick period", "They keep the calendar date and time of day", "They replace the task scheduler", "They are needed only inside virtual machines"]', 0, 'The tick sets a coarse time grid. Short deadlines and dense scheduling need timers that the hardware arms for exactly the right moment.');
